:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-surface: #f7f7f5;
  --color-stone-surface: #edece7;
  --color-frosted-glass: #ffffffe6;
  --color-plum-veil: #1b062499;
  --color-ember-ink: #160f0c;
  --color-jet-figure: #000000;
  --color-plum-ink: #1b0624;
  --color-graphite-ink: #292421;
  --color-ash-caption: #4d4846;
  --color-fog-caption: #898683;
  --color-lagoon-pulse: #45848d;
  --color-keylime-signal: #aeec1d;

  /* Typography — Font Families */
  --font-gt-america: "GT America", "Inter Tight", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.3;
  --tracking-small: 0.24px;
  --text-caption: 13px;
  --leading-caption: 1.4;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: -0.16px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.4px;
  --text-subheading: 24px;
  --leading-subheading: 1.4;
  --tracking-subheading: -0.72px;
  --text-heading-sm: 40px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -1.2px;
  --text-heading: 44px;
  --leading-heading: 1.1;
  --tracking-heading: -2.2px;
  --text-heading-lg: 72px;
  --leading-heading-lg: 1;
  --tracking-heading-lg: -4.32px;
  --text-display: 80px;
  --leading-display: 1;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-128: 128px;
  --spacing-140: 140px;

  /* Layout */
  --page-max-width: 1200px;
  --section-gap: 128px;
  --card-padding: 40px;
  --element-gap: 16px;

  /* Border Radius */
  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-2xl: 60px;
  --radius-full: 999px;

  /* Named Radii */
  --radius-cards: 24px;
  --radius-images: 24px;
  --radius-buttons: 999px;
  --radius-pills: 999px;
  --radius-tags: 999px;
  --radius-badges: 999px;
  --radius-innerTiles: 16px;
  --radius-smallCards: 8px;
  --radius-smallElements: 8px;
  --radius-inputs: 8px;
  --radius-alertBanners: 14px;
  --radius-sections: 60px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.05) 0px 0px 0px 1px inset;
  --shadow-md: rgba(45, 32, 50, 0.08) 0px 0.6px 1.8px -0.67px, rgba(45, 32, 50, 0.09) 0px 2.29px 6.87px -1.33px, rgba(45, 32, 50, 0.12) 0px 10px 30px -2px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-surface: #f7f7f5;
  --surface-stone-surface: #edece7;
  --surface-frosted-glass: #ffffffe6;
  --surface-ember-ink: #160f0c;
}

